// Rotate news sources based on day of week
const sources = [
  {
    name: 'Google News - Injection Molding',
    url: 'https://news.google.com/rss/search?q=injection+molding+OR+mold+making+OR+plastic+injection+OR+tooling&hl=en-US&gl=US&ceid=US:en',
    type: 'google'
  },
  {
    name: 'Google News - Reshoring & Manufacturing',
    url: 'https://news.google.com/rss/search?q=manufacturing+reshoring+OR+reshoring+OR+nearshoring+manufacturing&hl=en-US&gl=US&ceid=US:en',
    type: 'google'
  },
  {
    name: 'Google News - China Manufacturing',
    url: 'https://news.google.com/rss/search?q=china+manufacturing+OR+china+supply+chain+OR+china+tooling&hl=en-US&gl=US&ceid=US:en',
    type: 'google'
  },
  {
    name: 'Google News - Sustainable Manufacturing',
    url: 'https://news.google.com/rss/search?q=sustainable+manufacturing+OR+sustainable+plastics+OR+recycled+plastics&hl=en-US&gl=US&ceid=US:en',
    type: 'google'
  },
  {
    name: 'Google News - Tariffs & Trade',
    url: 'https://news.google.com/rss/search?q=china+tariffs+manufacturing+OR+trade+war+manufacturing+OR+import+tariffs+plastics&hl=en-US&gl=US&ceid=US:en',
    type: 'google'
  },
  {
    name: 'Google News - Automation & Industry 4.0',
    url: 'https://news.google.com/rss/search?q=manufacturing+automation+OR+industry+4.0+OR+smart+manufacturing&hl=en-US&gl=US&ceid=US:en',
    type: 'google'
  },
  {
    name: 'Google News - Automotive & Medical Molding',
    url: 'https://news.google.com/rss/search?q=automotive+injection+molding+OR+medical+injection+molding+OR+medical+device+manufacturing&hl=en-US&gl=US&ceid=US:en',
    type: 'google'
  }
];

const now = new Date();
const dayOfWeek = now.getDay();
const hour = now.getHours();
const sourceIndex = (dayOfWeek * 2 + (hour > 12 ? 1 : 0)) % sources.length;

const selectedSource = sources[sourceIndex];

return [{
  json: {
    sourceName: selectedSource.name,
    sourceUrl: selectedSource.url,
    sourceType: selectedSource.type
  }
}];

// Extract news items and pick a random one
const data = $input.first().json;
let items = [];

if (data.rss && data.rss.channel && data.rss.channel.item) {
  items = Array.isArray(data.rss.channel.item) ? data.rss.channel.item : [data.rss.channel.item];
} else if (data.feed && data.feed.entry) {
  items = Array.isArray(data.feed.entry) ? data.feed.entry : [data.feed.entry];
}

if (items.length === 0) {
  return [{ json: { error: 'No articles found', title: 'Industry insights from the field', source: 'Industry Experience', link: '' } }];
}

const randomIndex = Math.floor(Math.random() * Math.min(items.length, 10));
const article = items[randomIndex];

const title = article.title && typeof article.title === 'object' ? article.title['#text'] || article.title._ || String(article.title) : article.title || 'Industry Update';
let link = article.link && typeof article.link === 'object' ? article.link.href || article.link['#text'] || String(article.link) : article.link || '';
const source = article.source ? (article.source['#text'] || article.source._ || String(article.source)) : 'Industry News';

// Handle Google News redirect URLs
if (link.includes('news.google.com')) {
  // Extract the actual URL from Google News redirect
  const match = link.match(/url=([^&]+)/);
  if (match) {
    link = decodeURIComponent(match[1]);
  }
}

return [{
  json: {
    title: title,
    link: link,
    source: source
  }
}];

// Extract Open Graph image from article HTML
const input = $input.first().json;
const html = input.data || input.body || '';
const prevData = $('Extract Random Article').first().json;

let imageUrl = '';

// Try to find og:image
const ogImageMatch = html.match(/<meta[^>]*property=["']og:image["'][^>]*content=["']([^"']+)["']/i)
  || html.match(/<meta[^>]*content=["']([^"']+)["'][^>]*property=["']og:image["']/i);

if (ogImageMatch && ogImageMatch[1]) {
  imageUrl = ogImageMatch[1];
}

// Fallback: try twitter:image
if (!imageUrl) {
  const twitterImageMatch = html.match(/<meta[^>]*name=["']twitter:image["'][^>]*content=["']([^"']+)["']/i)
    || html.match(/<meta[^>]*content=["']([^"']+)["'][^>]*name=["']twitter:image["']/i);
  if (twitterImageMatch && twitterImageMatch[1]) {
    imageUrl = twitterImageMatch[1];
  }
}

// Fallback: first large image in article
if (!imageUrl) {
  const imgMatch = html.match(/<img[^>]*src=["']([^"']+(?:jpg|jpeg|png|webp)[^"']*)["'][^>]*>/i);
  if (imgMatch && imgMatch[1]) {
    imageUrl = imgMatch[1];
  }
}

// Clean up relative URLs
if (imageUrl && !imageUrl.startsWith('http')) {
  try {
    const urlObj = new URL(prevData.link);
    imageUrl = new URL(imageUrl, urlObj.origin).href;
  } catch (e) {
    imageUrl = '';
  }
}

return [{
  json: {
    title: prevData.title,
    link: prevData.link,
    source: prevData.source,
    imageUrl: imageUrl
  }
}];

// Prepare data for Claude, carrying forward image binary if exists
const imageData = $('Extract Article Image').first().json;
const binaryData = $input.first().binary;

return [{
  json: {
    title: imageData.title,
    link: imageData.link,
    source: imageData.source,
    imageUrl: imageData.imageUrl,
    hasImage: !!binaryData && !!binaryData.data
  },
  binary: binaryData
}];
